    result->size = {std::max<Integer>(0, width), std::max<Integer>(0, height)};
    const auto count = static_cast<std::size_t>(result->size.width) * static_cast<std::size_t>(result->size.height);
    result->rgba.resize(count * 4);
    for (std::size_t i = 0; i < count; ++i) {
        result->rgba[i * 4] = colour.r; result->rgba[i * 4 + 1] = colour.g;
        result->rgba[i * 4 + 2] = colour.b; result->rgba[i * 4 + 3] = colour.a;
    }
