void BillSprite::initialize(std::shared_ptr<::cw::sprite::bill::Bill> arg_bill)
{
    if(!arg_bill)throw std::invalid_argument("Bill is null");
    // Python と同様、スプライトを構築して画像を作ってから、add_layer(..., LAYER_LOG) で追加する。
    ::cw::sprite::base::CWPySprite::initialize({});
    m_bill=std::move(arg_bill);m_selections=m_bill->m_selections;m_specialchars=m_bill->m_specialchars;m_rect_noscale=m_bill->m_rect_noscale;
    m_tlayer=::cw::g_LAYER_LOG;
    update_scale();
    if (::cw::g_cwpy && m_ui_backend) {
        ::cw::lib::Arguments groups;
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_backloggrp.storage()); object && *object)
            groups.emplace_back(*object);
        if (!groups.empty()) m_ui_backend->register_sprite(*this, groups);
    }
}

void BillSprite::set_backlog_position(::cw::lib::Integer arg_y_noscale)
{
    m_rect_noscale.y = arg_y_noscale;
    // ネイティブの配置 API も、Py の cw.s(Rect) と同じ切り捨て規則を使う。
    m_rect.y = static_cast<::cw::lib::Integer>(arg_y_noscale * ::cw::g_UP_SCR);
    if (!m_ui_backend) m_ui_backend = ::cw::sprite::base::sprite_ui_backend();
    if (m_ui_backend) m_ui_backend->invalidate(*this, m_rect);
}

void BillSprite::update_scale()
{
    if(!m_bill)throw std::logic_error("BillSprite has no Bill");
    auto [image,unused_rect]=m_bill->create_image();
    (void)unused_rect;
    m_image=std::move(image);
    // create_image() の矩形は Bill の入力内の座標を表す。
    // バックログのスプライトは配置を別に持つため、画像再構築で set_backlog_position()
    // が設定した y 座標をリセットしない。
    m_rect={
        static_cast<::cw::lib::Integer>(m_rect_noscale.x*::cw::g_UP_SCR),
        static_cast<::cw::lib::Integer>(m_rect_noscale.y*::cw::g_UP_SCR),
        static_cast<::cw::lib::Integer>(m_rect_noscale.width*::cw::g_UP_SCR),
        static_cast<::cw::lib::Integer>(m_rect_noscale.height*::cw::g_UP_SCR)};
    if (!m_ui_backend) m_ui_backend = ::cw::sprite::base::sprite_ui_backend();
    if (m_ui_backend) m_ui_backend->update_scale(*this);
}

